{
  "name": "opencode-tabs",
  "version": "0.3.0",
  "description": "Session tabs for the OpenCode TUI",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/Minhir/opencode-tabs.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin"
  ],
  "type": "module",
  "files": [
    "dist"
  ],
  "exports": {
    "./tui": "./dist/tui.mjs"
  },
  "engines": {
    "opencode": ">=1.17.20"
  },
  "scripts": {
    "build": "tsdown",
    "check": "bun run typecheck && bun run lint && bun run test && bun run knip && bun run build",
    "knip": "knip-bun",
    "lint": "biome check",
    "prepack": "bun run check",
    "test": "vitest run",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opentui/solid": "^0.4.5",
    "solid-js": "^1.9.12"
  },
  "peerDependenciesMeta": {
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@babel/core": "7.29.7",
    "@babel/preset-typescript": "7.29.7",
    "@biomejs/biome": "2.5.6",
    "@opencode-ai/plugin": "1.18.10",
    "@opentui/core": "0.4.5",
    "@opentui/keymap": "0.4.5",
    "@opentui/solid": "0.4.5",
    "@rollup/plugin-babel": "7.1.0",
    "@types/node": "^24.13.3",
    "babel-preset-solid": "1.9.12",
    "knip": "^6.31.0",
    "solid-js": "1.9.14",
    "tsdown": "0.22.14",
    "typescript": "~7.0.2",
    "vitest": "4.1.10"
  }
}
